        "id": "mkwn4110-pancasila-2",
        "number": 2,
        "question": "Pernyataan yang paling tepat untuk menjelaskan peran Pancasila sebagai bagian penting bagi masyarakat dan negara dalam konteks dulu dan kini adalah ….",
