        "number": 4,
        "question": "Dalam diskusi mahasiswa, seorang peserta berpendapat: “Dasar negara berfungsi sebagai acuan dalam penyusunan hukum dasar negara, sehingga semua peraturan harus sesuai nilai-nilai Pancasila.” Pernyataan tersebut paling sesuai dengan definisi ....",
