        "id": "mkwn4110-pancasila-94",
        "number": 94,
        "question": "Dalam kuliah hukum tata negara, dosen menjelaskan: “Dasar negara adalah norma dasar yang menjadi cita-cita hukum tertinggi dan berfungsi mengarahkan seluruh peraturan hukum.” Pandangan tersebut sesuai dengan pemikiran ....",
