        "number": 122,
        "question": "Dalam persaingan ekonomi global, Indonesia membuka investasi asing tetapi tetap melindungi UMKM dan menata pasar agar adil. Respons ini menunjukkan Pancasila sebagai ideologi terbuka karena ….",
