        "id": "mkwn4110-pancasila-123",
        "number": 123,
        "question": "Sejumlah mahasiswa di sebuah universitas negeri terdeteksi terlibat kelompok diskusi tertutup yang menyebarkan paham radikal melalui media sosial. Mereka menolak demokrasi dan mendorong berdirinya negara baru berbasis agama tertentu. Bagaimana Pancasila difungsikan sebagai paradigma pembangunan ketahanan nasional dalam menghadapi kasus tersebut?",
