        "id": "mkwn4110-pancasila-124",
        "number": 124,
        "question": "Nilai-nilai Pancasila diwujudkan dalam kehidupan nyata, misalnya sila Persatuan Indonesia tercermin pada kegiatan gotong royong warga membangun jembatan desa, dan sila Kerakyatan terlihat dalam musyawarah warga untuk mengambil keputusan bersama. Contoh tersebut termasuk landasan …. Pancasila.",
