        "id": "mkwn4110-pancasila-125",
        "number": 125,
        "question": "Tingginya kasus perundungan (bullying) di sekolah yang viral di media sosial menunjukkan lemahnya pengamalan nilai kemanusiaan dalam kehidupan sehari-hari. Tantangan implementasi Pancasila di bidang sosial dari kasus tersebut adalah ….",
