        "id": "mkwn4110-pancasila-126",
        "number": 126,
        "question": "Pemerintah kota merencanakan pembangunan taman kota besar sebagai ruang publik. Namun, di lokasi pembangunan terdapat rumah ibadah yang sudah lama digunakan masyarakat. Untuk itu, pemerintah berdiskusi dengan pemuka agama dan warga, lalu membangun taman di lokasi lain sekaligus memperbaiki akses jalan menuju rumah ibadah agar tetap nyaman digunakan. Analisis yang tepat mengenai implementasi nilai ketuhanan dalam paradigma pembangunan adalah ….",
