        "number": 128,
        "question": "Pemerintah membangun jalan nasional yang menghubungkan wilayah terpencil dengan kota besar. Pembangunan ini dilakukan dengan melibatkan semua pemerintah daerah terkait dan memperhatikan kebutuhan masyarakat lokal. Jika dianalisis berdasarkan implementasi sila ketiga Pancasila: Persatuan Indonesia, maka dampak positif dari kebijakan tersebut adalah ….",
