        "number": 129,
        "question": "Pemerintah melaksanakan program pembangunan bendungan untuk mengatasi krisis air dan meningkatkan produksi pertanian. Namun, pembangunan ini menimbulkan dampak sosial berupa relokasi masyarakat desa sekitar bendungan. Sebagian warga menilai proses relokasi dilakukan terburu-buru dan kompensasi yang diberikan tidak sesuai kebutuhan hidup layak. Jika dianalisis dari perspektif implementasi sila kedua Pancasila: Kemanusiaan yang Adil dan Beradab, maka kebijakan pembangunan tersebut seharusnya ….",
