        "id": "mkwn4110-pancasila-130",
        "number": 130,
        "question": "Mahasiswa sering menghadapi persoalan etika akademik, seperti plagiarisme, intoleransi, dan kurangnya tanggung jawab sosial. Situasi ini menunjukkan perlunya pemahaman Pancasila bukan hanya sebagai dasar negara, tetapi juga sebagai pedoman etis dalam kehidupan nyata. Kasus tersebut menggambarkan bahwa ruang lingkup Pendidikan Pancasila mencakup hal-hal berikut, yaitu ….",
