        "id": "mkwn4110-pancasila-132",
        "number": 132,
        "question": "Pemerintah membangun jalan tol baru untuk memperlancar distribusi barang. Namun, tarif tol dinilai terlalu mahal sehingga hanya kelompok ekonomi menengah ke atas yang dapat menikmatinya. Analisis implementasi nilai keadilan dari kasus tersebut adalah ….",
