        "id": "mkwn4110-pancasila-133",
        "number": 133,
        "question": "Dalam kehidupan kampus yang semakin terhubung dengan dunia global, mahasiswa sering berinteraksi tidak hanya dengan sesama mahasiswa dari berbagai suku, agama, dan budaya di Indonesia, tetapi juga dengan mahasiswa asing. Situasi ini menuntut adanya sikap saling menghormati, kemampuan beradaptasi, dan penghargaan terhadap nilai-nilai universal. Berdasarkan kasus tersebut, apa urgensi Pendidikan Pancasila bagi mahasiswa?",
