        "number": 134,
        "question": "Pemerintah merancang kebijakan subsidi pupuk bagi petani kecil agar mereka tetap bisa berproduksi meski harga pasar pupuk tinggi. Kebijakan ini dibuat dengan pertimbangan keadilan sosial dan kesejahteraan rakyat, yang merujuk pada nilai-nilai dasar Pancasila. Berdasarkan kasus tersebut, tujuan Pendidikan Pancasila yang paling tepat adalah ....",
